def minimum_length_encoding(words):
    root = {}
    word_end_node = {}

    unique_words = list(set(words))

    for word in unique_words:
        node = root
        for ch in reversed(word):
            node = node.setdefault(ch, {})
        word_end_node[word] = node

    total = 0
    for word in unique_words:
        node = word_end_node[word]
        if not node:
            total += len(word) + 1

    return total

